import React, { useState, useEffect } from 'react';
import { Github, Linkedin, Mail, ExternalLink, Database, Cloud, Brain, Download, Menu, X, ArrowRight, Sparkles, Zap, Target } from 'lucide-react';

const Portfolio = () => {
  const [scrollY, setScrollY] = useState(0);
  const [activeSection, setActiveSection] = useState('hero');
  const [typedText, setTypedText] = useState('');
  const fullText = "AI & Machine Learning Engineer";

  // Typing effect for the headline
  useEffect(() => {
    if (typedText.length < fullText.length) {
      const timeout = setTimeout(() => {
        setTypedText(fullText.slice(0, typedText.length + 1));
      }, 100);
      return () => clearTimeout(timeout);
    }
  }, [typedText]);

  // Handle scroll for navbar styling
  useEffect(() => {
    const handleScroll = () => {
      setScrollY(window.scrollY);
      const sections = ['hero', 'experience', 'projects', 'skills'];
      const current = sections.find(section => {
        const element = document.getElementById(section);
        if (element) {
          const rect = element.getBoundingClientRect();
          return rect.top <= 150 && rect.bottom >= 150;
        }
        return false;
      });
      if (current) setActiveSection(current);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const projects = [
    {
      title: "Intelligent SQL-Gen",
      subtitle: "NLP to SQL via RAG Architecture",
      description: "Designed a RAG-based system that converts natural language queries into accurate SQL queries using Azure OpenAI and LangChain. Implemented semantic schema linking via FAISS to identify relevant tables and reduce hallucinations.",
      tags: ["Azure OpenAI", "LangChain", "FAISS", "Streamlit"],
      icon: "💬",
      gradient: "from-blue-500 to-cyan-600"
    },
    {
      title: "Deep Farming",
      subtitle: "Crop Disease Surveillance",
      description: "Developed a smart farming solution using CNN models and TensorFlow to detect crop diseases with high accuracy. Deployed via a Flask web application for real-time predictions.",
      tags: ["Python", "TensorFlow", "CNN", "Flask"],
      icon: "🌱",
      gradient: "from-green-500 to-emerald-600"
    },
    {
      title: "Healthcare Guidance Navigator",
      subtitle: "Agentic AI Clinical Support",
      description: "Built a healthcare chatbot using Agentic AI and LangGraph to provide document-specific clinical guidance from PDFs and CSV files.",
      tags: ["Agentic AI", "ChromaDB", "LangGraph", "Azure OpenAI"],
      icon: "🏥",
      gradient: "from-pink-500 to-rose-600"
    }
  ];

  return (
    <div className="bg-black text-white min-h-screen relative font-sans selection:bg-purple-500/30">
      
      {/* --- DATA SCIENCE & AI BACKGROUND ELEMENTS --- */}
      <div className="fixed inset-0 z-0 overflow-hidden pointer-events-none">
        {/* Abstract AI/Neural Network Image */}
        <div 
          className="absolute inset-0 opacity-10 grayscale brightness-50"
          style={{ 
            backgroundImage: `url('https://images.unsplash.com/photo-1677442136019-21780ecad995?auto=format&fit=crop&q=80&w=2000')`,
            backgroundSize: 'cover',
            backgroundPosition: 'center',
          }}
        ></div>
        
        {/* Animated Digital Grid */}
        <div className="absolute inset-0 opacity-20" 
             style={{ backgroundImage: 'linear-gradient(#2a2a2a 1px, transparent 1px), linear-gradient(90deg, #2a2a2a 1px, transparent 1px)', backgroundSize: '50px 50px' }}>
        </div>

        {/* Purple and Blue Ambient Glows */}
        <div className="absolute top-[-10%] left-[-10%] w-[60%] h-[60%] bg-purple-600/10 blur-[120px] rounded-full animate-pulse"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[60%] h-[60%] bg-blue-600/10 blur-[120px] rounded-full animate-pulse" style={{ animationDelay: '2s' }}></div>
      </div>

      {/* Navigation */}
      <nav className={`fixed top-0 w-full z-50 transition-all duration-300 ${scrollY > 50 ? 'backdrop-blur-xl bg-black/80 border-b border-white/10' : 'bg-transparent'}`}>
        <div className="max-w-7xl mx-auto px-6 py-5 flex justify-between items-center">
          <div className="text-xl font-black tracking-tighter">
            ROHIT <span className="text-purple-500 uppercase">Harne</span>
          </div>
          <div className="hidden md:flex gap-10 items-center">
            {['Experience', 'Projects', 'Skills'].map((item) => (
              <a key={item} href={`#${item.toLowerCase()}`} className={`text-xs uppercase tracking-widest font-bold hover:text-purple-400 transition-colors ${activeSection === item.toLowerCase() ? 'text-purple-400' : 'text-gray-400'}`}>
                {item}
              </a>
            ))}
            <a href="mailto:rohitharne21@gmail.com" className="px-6 py-2 bg-gradient-to-r from-purple-600 to-blue-600 rounded-full text-xs font-bold hover:scale-105 transition-all shadow-lg shadow-purple-500/20">
              GET IN TOUCH
            </a>
          </div>
        </div>
      </nav>

      {/* Hero Section */}
      <section id="hero" className="relative min-h-screen flex items-center justify-center px-6 z-10">
        <div className="max-w-7xl mx-auto w-full grid md:grid-cols-2 gap-12 items-center">
          <div>
            <div className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-white/5 border border-white/10 text-[10px] font-bold tracking-widest text-purple-400 mb-8 uppercase">
              <span className="w-2 h-2 bg-purple-500 rounded-full animate-ping"></span>
              Specializing in Generative AI
            </div>
            <h1 className="text-6xl md:text-8xl font-black mb-6 leading-[0.85] tracking-tighter">
              AI <br /><span className="bg-gradient-to-r from-purple-400 via-pink-400 to-blue-400 bg-clip-text text-transparent uppercase">Engineer</span>
            </h1>
            <div className="h-12 mb-6">
              <p className="text-2xl md:text-3xl font-light text-gray-400">
                {typedText}<span className="text-purple-500 animate-pulse">_</span>
              </p>
            </div>
            <p className="text-gray-400 text-lg max-w-lg mb-10 leading-relaxed">
              Experienced in building end-to-end AI solutions across healthcare and analytics domains. Based in Pune, MH.
            </p>
            <div className="flex flex-wrap gap-4">
              <a href="#projects" className="px-8 py-4 bg-white text-black rounded-full font-bold hover:bg-purple-600 hover:text-white transition-all flex items-center gap-2">
                View My Work <ArrowRight className="w-4 h-4" />
              </a>
              {/* FIXED RESUME DOWNLOAD PATH */}
              <a href="/Rohit_Harne.Resume--.pdf" download className="px-8 py-4 border border-white/20 rounded-full font-bold hover:bg-white/10 transition-all flex items-center gap-2">
                <Download className="w-4 h-4" /> Download CV
              </a>
            </div>
          </div>

          <div className="relative flex justify-center">
            <div className="relative group">
              {/* Outer Glow */}
              <div className="absolute -inset-4 bg-gradient-to-tr from-purple-600 to-blue-600 rounded-[2.5rem] blur-2xl opacity-20 group-hover:opacity-40 transition duration-1000"></div>
              
              {/* FIXED PROFILE IMAGE PATH: Since it's in /public/profile.jpg */}
              <img 
                src="/profile.jpg" 
                alt="Rohit Harne" 
                className="relative w-80 h-96 md:w-96 md:h-[500px] object-cover rounded-[2rem] border border-white/10 shadow-2xl grayscale group-hover:grayscale-0 transition-all duration-700"
              />
              
              <div className="absolute -bottom-6 -right-6 p-6 bg-black/90 backdrop-blur-xl border border-white/10 rounded-2xl shadow-2xl">
                <div className="flex items-center gap-3">
                  <div className="p-3 bg-purple-500/20 rounded-xl">
                    <Database className="w-6 h-6 text-purple-400" />
                  </div>
                  <div>
                    <p className="text-[10px] uppercase tracking-widest text-gray-500 font-bold">Industry Exp.</p>
                    <p className="text-xl font-bold">6 Months</p>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Experience Section */}
      <section id="experience" className="py-32 px-6 z-10 relative bg-white/[0.01]">
        <div className="max-w-4xl mx-auto">
          <h2 className="text-4xl font-black mb-16 tracking-tighter uppercase italic">Professional Experience</h2>
          <div className="relative border-l-2 border-purple-500/30 pl-8 ml-4">
            <div className="absolute -left-[9px] top-0 w-4 h-4 bg-purple-500 rounded-full shadow-[0_0_15px_rgba(168,85,247,0.5)]"></div>
            <p className="text-purple-400 font-bold tracking-widest text-xs uppercase mb-2">AI & ML Intern</p>
            <h3 className="text-2xl font-bold text-white mb-1">Vcitysoft Pvt. Ltd.</h3>
            <p className="text-gray-500 text-sm mb-6 font-medium tracking-widest">6 MONTHS</p>
            <ul className="space-y-4 text-gray-400">
              <li className="flex gap-3"><span className="text-purple-500 mt-1.5 w-1.5 h-1.5 rounded-full bg-purple-500 shrink-0"></span> Developed end-to-end analytical and AI solutions across financial and healthcare domains using Python.</li>
              <li className="flex gap-3"><span className="text-purple-500 mt-1.5 w-1.5 h-1.5 rounded-full bg-purple-500 shrink-0"></span> Built scalable, production-ready Python applications using OOP and Flask framework.</li>
              <li className="flex gap-3"><span className="text-purple-500 mt-1.5 w-1.5 h-1.5 rounded-full bg-purple-500 shrink-0"></span> Worked extensively with SQL databases, data visualization, and core ML libraries.</li>
            </ul>
          </div>
        </div>
      </section>

      {/* Projects Section */}
      <section id="projects" className="py-32 px-6 z-10 relative">
        <div className="max-w-7xl mx-auto">
          <div className="mb-20">
            <h2 className="text-5xl font-black mb-4 tracking-tighter uppercase">Selected Projects</h2>
            <div className="w-20 h-1.5 bg-purple-600"></div>
          </div>
          <div className="grid md:grid-cols-3 gap-8">
            {projects.map((project, idx) => (
              <div key={idx} className="group p-8 bg-white/[0.03] border border-white/10 rounded-[2.5rem] hover:bg-white/[0.07] transition-all hover:-translate-y-2 border-t-purple-500/20">
                <div className="text-4xl mb-6 transform group-hover:scale-110 transition-transform">{project.icon}</div>
                <h3 className="text-2xl font-bold mb-3 group-hover:text-purple-400 transition-colors">{project.title}</h3>
                <p className="text-gray-400 text-sm mb-8 leading-relaxed line-clamp-4 font-light">{project.description}</p>
                <div className="flex flex-wrap gap-2 mb-10">
                  {project.tags.map(tag => (
                    <span key={tag} className="px-3 py-1 bg-white/5 rounded-lg text-[9px] font-bold tracking-widest uppercase text-gray-400 border border-white/5">{tag}</span>
                  ))}
                </div>
                <button className="flex items-center gap-2 text-[10px] font-black tracking-widest text-purple-400 hover:text-white transition-colors uppercase">
                  Explore Repository <Github className="w-4 h-4" />
                </button>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Footer */}
      <footer className="py-20 border-t border-white/5 relative z-10 bg-black/80 backdrop-blur-md">
        <div className="max-w-7xl mx-auto px-6 flex flex-col md:flex-row justify-between items-center gap-10">
          <div className="text-center md:text-left">
            <p className="text-2xl font-bold tracking-tighter mb-2">Let's solve the next <span className="text-purple-500 uppercase italic">Big Problem.</span></p>
            <p className="text-gray-500 text-xs tracking-widest uppercase font-medium">© 2025 Rohit Harne • AI & ML Engineer • Pune</p>
          </div>
          <div className="flex gap-4">
            <a href="https://linkedin.com" className="p-4 bg-white/5 rounded-2xl hover:bg-purple-600 transition-all border border-white/10"><Linkedin className="w-5 h-5" /></a>
            <a href="https://github.com" className="p-4 bg-white/5 rounded-2xl hover:bg-purple-600 transition-all border border-white/10"><Github className="w-5 h-5" /></a>
            <a href="mailto:rohitharne21@gmail.com" className="p-4 bg-white/5 rounded-2xl hover:bg-purple-600 transition-all border border-white/10"><Mail className="w-5 h-5" /></a>
          </div>
        </div>
      </footer>

    </div>
  );
};

export default Portfolio;
